from typing import Annotated
from pydantic import Field
from mcp.server.mcpserver.server import MCPServer

server = MCPServer('check')
try:
    @server.tool()
    def invalid(tags: Annotated[list[str], Field(json_schema_extra={'x-mcp-header': 'Tags'})]) -> str:
        return 'ok'
except ValueError as exc:
    print(type(exc).__name__, exc)
else:
    raise AssertionError('invalid schema registered')

@server.tool()
def valid(owner: Annotated[str, Field(json_schema_extra={'x-mcp-header': 'Owner'})]) -> str:
    return owner
print([tool.name for tool in server._tool_manager.list_tools()])
PY
"}

